contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    // params:
    //  initialFund - amount of wei to send into c via fallback (must be >= 0)
    //  callAmount - amount to attempt to withdraw
    // The test: if this contract is the owner of c (i.e. c.owner() == address(this)),
    // then after calling c.withdrawAll() the balance of c should be less than before
    // (i.e. some funds were transferred out). This holds for the original contract
    // but is violated by the mutant that inverts the onlyOwner check.
    function runTest(uint initialFund, uint callAmount) public payable {
        require(msg.value == initialFund, "send initialFund as msg.value");

        // Ensure this contract is the owner of c for the distinguishing scenario.
        // The provided C sets owner to its deployer; the constructor of this test
        // receives an existing C instance. The caller of runTest must ensure
        // that this contract is indeed the owner of c (precondition for the test).
        require(c.owner() == address(this), "this contract must be owner of c");

        // Fund contract c by sending ETH to it so there's something to withdraw.
        // Use the fallback payable by calling (address(c)).call with empty data.
        // This is a state-changing call on c and must be its own top-level statement.
        (bool ok,) = address(c).call{value: initialFund}("");
        require(ok, "funding c failed");

        uint before = address(c).balance;
        require(before >= callAmount, "not enough balance in c for requested withdraw");

        // Attempt to withdraw all using withdrawAll (requires onlyOwner in C)
        c.withdrawAll();

        uint after = address(c).balance;

        // If this contract is the owner, the original contract will allow withdrawAll
        // and thus reduce c's balance. The mutant flips the check and would prevent
        // the owner from calling withdrawAll, leaving the balance unchanged.
        assert(after < before);
    }

    // allow contract to receive ETH so runTest can send msg.value to this contract
    receive() external payable {}
}

