    C c;
    address owner;

    function setUp() public { 
        c = new C();
        owner = address(this); // the test contract is the deployer/owner
    }

    // The fuzzed parameter is the amount of ETH initially sent to the contract before withdrawAll.
    function testFuzz_property(uint256 depositAmount) public {
        // keep depositAmount within practical bounds but wide enough to find non-zero values
        depositAmount = bound(depositAmount, 0, 1 ether);

        // Fund the test contract (owner) so it can send ETH to c
        vm.deal(owner, depositAmount);

        // send depositAmount to c via its fallback by calling it with value
        if (depositAmount > 0) {
            // owner (this) sends ETH to c which increments depositsCount in fallback
            (bool ok, ) = address(c).call{value: depositAmount}("");
            require(ok);
        }

        // record balances before withdrawAll
