        uint256 beforeOwner = owner.balance;

        // call withdrawAll as owner (this contract is the owner)
        // use try/catch to comply with rules if any revert difference exists
        bool success;
        try c.withdrawAll() {
            success = true;
        } catch {
            success = false;
        }

        // After withdrawAll, the reference implementation guarantees the contract balance is fully forwarded to the owner.
