pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: attacker initial funding amount and a boolean to choose whether attacker funds via fallback
    function testFuzz_property(uint256 attackerFund, bool useFallback) public {
        // Keep domain wide but sensible: attackerFund in [1, 1e20]
        attackerFund = bound(attackerFund, 1, 1e20);

        // Deploy adversarial caller contract that will call withdrawAll
        Attacker attacker = new Attacker(address(c));

        // Fund attacker externally so it can send ETH when calling into C
        vm.deal(address(attacker), attackerFund);

        // The attacker will either send ETH by calling a payable fallback on C (which increments depositsCount)
        // or call sendMoney to transfer funds into C under its msg.sender
        if (useFallback) {
            // attacker sends funds via low-level call to trigger fallback
            attacker.fundViaFallback{value: attackerFund}();
        } else {
            // attacker uses C.sendMoney to transfer funds into C (C will record deposits if fallback is triggered by direct call?)
            // sendMoney forwards a call to target; calling sendMoney will let attacker be msg.sender on the forwarded call
            attacker.fundViaSendMoney{value: attackerFund}();
        }

        // Record contract balance before attacker tries to withdrawAll
        uint256 beforeBalance = address(c).balance;
        address ownerBefore = c.owner();

        // Attacker attempts to call withdrawAll from its own contract (non-owner)
        bool ok;
        try attacker.callWithdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: for the correct contract C, regardless of attackerFund and useFallback, the owner remains unchanged
        // and the contract balance is NOT decreased by the attacker (i.e., attacker cannot withdrawAll unless it is owner).
        // We assert a single predicate reading c: address(c).balance == beforeBalance && c.owner() == ownerBefore
        // This holds for the reference; the mutant (withdrawAll without onlyOwner) allows the attacker to drain funds,
        // making address(c).balance < beforeBalance and possibly transferring to attacker.
        assertTrue(address(c).balance == beforeBalance && c.owner() == ownerBefore);
    }
}

// Minimal adversarial helper that can fund C and then call withdrawAll
contract Attacker {
    address payable immutable target;
    constructor(address _target) payable {
        target = payable(_target);
    }

    // Fund C via fallback by making a plain payable call
    function fundViaFallback() external payable {
        // call target with empty data to hit fallback()
        (bool s, ) = target.call{value: msg.value}("");
        require(s);
    }

    // Fund C via calling sendMoney on C so attacker is the sender of the forwarded call
    function fundViaSendMoney() external payable {
        // call sendMoney on C: function sendMoney(address,uint,bytes)
        // Compose calldata for sendMoney(address,uint256,bytes)
        C(target).sendMoney(address(this), msg.value, "");
    }

    // Call withdrawAll on target
    function callWithdrawAll() external {
        C(target).withdrawAll();
    }

    // Allow receiving ether when withdrawAll succeeds (in mutant)
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Provide funds to this test contract so it can forward them to C when calling payable functions
    receive() external payable {}

    // Drive the minimal sequence: send ether to C (via fallback), then call withdrawAll as owner.
    // After withdrawAll returns, C.balance must be zero.
    function runTest(uint depositAmount) public payable {
        require(msg.value == depositAmount, "must forward depositAmount as msg.value");
        require(depositAmount > 0, "need positive deposit");

        // send Ether to C so its fallback increments depositsCount and increases its balance
        // Using call to transfer Ether from this contract
        (bool s,) = address(c).call{value: depositAmount}("");
        require(s, "funding C failed");

        // Ensure C received funds
        require(address(c).balance == depositAmount, "unexpected C balance before withdraw");

        // Now call withdrawAll as owner: this contract must be the owner of C for the rule to hold.
        // The constructor of C set owner to deployer; the test assumes the test contract is owner.
        c.withdrawAll();

        // After successful withdrawAll, C's balance must be zero (i.e., withdraw must not fail silently)
        assert(address(c).balance == 0);
    }
}

