// adversarial callee: either accepts funds or reverts in fallback/receive
contract Callee {
    bool public willRevert;
    constructor(bool _willRevert) payable {
        willRevert = _willRevert;
    }
    receive() external payable {
        if (willRevert) revert("revert receive");
    }
    fallback() external payable {
        if (willRevert) revert("revert fallback");
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // call sequence driven by parameters:
    // - fundAmount: amount of wei this test contract must hold prior to calling fundTarget
    // - fundToContract: amount to send into c so it has a nonzero balance
    // - callerIsOwner: if true, this contract will be the owner of c (must hold when C was deployed);
    // We don't check or change owner inside test; we only observe whether withdraw succeeds when called by this contract.

    // The function performs: send ETH to C (to set its balance) and then attempts withdrawAll from C.
    // On the original contract P, only the actual owner can withdraw, so if this contract is not owner, withdrawAll will revert and no balance is sent out.
    // On the mutant M (onlyOwner omitted), withdrawAll will succeed and transfer C's balance to this contract, changing address(this).balance.

    function checkWithdrawBehavior(uint fundToContract, uint /*unused */, uint /*unused2*/) public payable {
        // ensure this contract has enough balance to fund C
        require(address(this).balance >= fundToContract, "insufficient balance to fund C");

        // fund C by invoking its fallback via a direct payable call
        (bool ok, ) = address(c).call{value: fundToContract}("\x00");
        require(ok, "funding C failed");

        // record our balance before attempting withdrawAll
        uint before = address(this).balance;

        // attempt to withdraw all from C; behavior differs between P (revert for non-owner) and M (succeeds)
        // This is a state-changing call and must be top-level.
        try c.withdrawAll() {
            // call succeeded
        } catch {
            // call reverted
        }

        uint after = address(this).balance;

        // General rule: if this contract is NOT the owner, it cannot increase its balance by calling withdrawAll on c.
        // We express that as: after <= before
        assert(after <= before);
    }

    // allow contract to receive ETH for funding
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Drive the behavior: send value to a target which in its fallback increments its depositsCount.
    // We observe that under the original contract P, sendMoney does not revert when the low-level call fails,
    // so depositsCount of the target contract (c) is increased even if the external call failed and P did not revert.
    // Under mutant M (which requires ok), the transaction would revert on a failing call and depositsCount would not be observable changed.

    // We implement the test as follows:
    // - require this contract has enough balance to forward value
    // - call c.sendMoney with given target, value, data
    // - afterwards assert that either the call returned (i.e., no revert) and depositsCount increased, expressed by comparing c.depositsCount to expected value

    // The single public test function takes parameters so a verifier can instantiate values.
    function run(address _target, uint _value, bytes calldata _data, uint beforeCount) public payable {
        require(address(this).balance >= _value, "insufficient balance");

        // record depositsCount before the call using the public getter
        uint prev = c.depositsCount();
        require(prev == beforeCount, "precondition mismatch");

        // perform the state-changing call on c
        c.sendMoney(_target, _value, _data);

        // observe depositsCount after
        uint after = c.depositsCount();

        // General rule: after >= prev (the call does not revert and any fallback side-effect persists)
        assert(after >= prev);
    }

    // Allow this contract to receive ETH so it can forward funds
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // sendMoney will be called with a nonzero value to exercise low-level call behavior
    function run(address target, uint amount, bytes calldata data) public payable {
        require(amount > 0, "amount must be > 0");
        // ensure this contract can send the requested amount
        require(address(this).balance >= amount, "insufficient balance");

        bool reverted;
        try c.sendMoney{value: amount}(target, amount, data) { reverted = false; } catch { reverted = true; }

        // General rule: in the original contract P, sendMoney never reverts solely because the callee failed; thus for any (target,amount,data) with amount>0 the call should not revert.
        // This is violated by the mutant which requires the call's success and will revert when the callee fails.
        assert(reverted == false);
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will call sendMoney forwarding `amount` wei to `target` with arbitrary data.
    // The rule: if `target` is not a contract (i.e., has no code) then sending ETH via sendMoney should not revert in the original contract.
    function run(address target, uint amount, bytes calldata data) public payable {
        require(address(this).balance >= amount, "insufficient balance for test");
        // Precondition: target must be an EOA (no contract code). This is the separating condition.
        require(target.code.length == 0, "target must be EOA");
        bool reverted;
        try c.sendMoney{value: amount}(target, amount, data) { reverted = false; } catch { reverted = true; }
        // General rule: when target is an EOA (no code) and amount >= 0, sendMoney should not revert.
        assert(reverted == false);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address target, uint amount, bytes calldata data) public payable {
        // We require no precondition: instead we assert the general rule that sending 0 value never reverts.
        // Call sendMoney with provided params, forwarding `amount` wei from this contract.
        require(address(this).balance >= amount);
        bool reverted;
        try c.sendMoney{value: amount}(target, amount, data) { reverted = false; } catch { reverted = true; }
        // The general rule: if amount == 0 then the call should not revert on the original contract P.
        assert(amount == 0 ? reverted == false : true);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address target, uint value, bytes calldata data) public payable {
        require(true);
        // ensure we don't accidentally send ETH from this contract when value==0
        bool reverted;
        try c.sendMoney{value: value}(target, value, data) {
            reverted = false;
        } catch {
            reverted = true;
        }
        // General rule: zero-value calls to sendMoney should never revert
        assert(value != 0 || reverted == false);
    }
    receive() external payable {}
}
